// eslint-disable
'use strict';

const logger = require('@yandex-int/yandex-logger')();

// 1. Простое сообщение
logger.info('Log message');

// 2. Логируем только ошибку
let err = new Error('Something went wrong!');
logger.error(err);

// 3. Логируем ошибку и дополнительную информацию о запросе
let req = require('./entry').req;
logger.error({
    req,
    err,
});
